  public void UpdateSelection(){
   if(game.phase!=GamePhase.Rest||cards.Count!=3)return;bool chosen=game.pendingUpgrade!=null;
   for(int i=0;i<cards.Count;i++){bool selected=game.offers[i]==game.pendingUpgrade;cardGroups[i].alpha=chosen&&!selected?.65f:1;cardFrames[i].Select(selected);}
   confirm.interactable=chosen;cardHealth.text=$"气血 {game.hp:0.#} / {game.MaxHP:0.#} · 三选一，确认前可更换";
   if(!chosen){cardPreview.text="点击一张卡修炼 · 不限选择时间";return;}
   var u=Array.Find(game.data.upgrades,v=>v.id==game.pendingUpgrade);var copy=game.run.Clone();float preview=Rules.Apply(game.data,copy,u.id,game.hp);
   cardHealth.text=$"气血 {game.hp:0.#} → {preview:0.#} / {copy.maxHp:0.#} · 确认后生效";
   cardPreview.text=$"已选「{u.name}」· 可改选 · 确认后继续";
  }
  public void ShowFormationDamage(float damage,float x,float y,bool heavy){if(!formationFeedback)return;feedbackAt=game.clock;feedbackUntil=game.clock+.65f;feedbackX=x+62;feedbackY=y-66;feedbackPunch=heavy?1.3f:1.16f;formationFeedback.text=$"{damage:0.#}";formationFeedback.gameObject.SetActive(true);}
  public void ClearFormationDamage(){feedbackUntil=-1;if(formationFeedback)formationFeedback.gameObject.SetActive(false);}
  void RefreshFormationDamage(){if(!formationFeedback)return;bool show=game.clock<feedbackUntil&&!HasModal&&game.phase==GamePhase.Play;formationFeedback.gameObject.SetActive(show);if(!show)return;var viewport=game.gameCamera.WorldToViewportPoint(PixelWorld.Position(feedbackX,feedbackY));formationFeedback.rectTransform.anchoredPosition=new Vector2(viewport.x*1280-55,-((1-viewport.y)*720-24));float age=game.clock-feedbackAt;formationFeedback.rectTransform.localScale=Vector3.one*Mathf.Lerp(feedbackPunch,1,Mathf.Clamp01(age/.16f));formationFeedback.color=new Color(1,.87f,.60f,Mathf.Clamp01((feedbackUntil-game.clock)/.2f));}
