  public void Refresh(){if(!hud)return;RefreshFormationDamage();bool active=game.phase!=GamePhase.Menu&&game.phase!=GamePhase.Story;hud.gameObject.SetActive(active);if(!active)return;hpText.text=$"气血  {game.hp:0.#} / {game.MaxHP:0.#}";hpFill.rectTransform.sizeDelta=new Vector2(208*Mathf.Clamp01(game.hp/game.MaxHP),13);placeText.text=game.endless?$"轮回剑境 · 第 {game.run.wave} 波{game.ReinforcementLabel}":game.data.rooms[game.room].name;CD(kText,kFill,"飞剑",game.rangedReady,game.settings.rangedCooldown*game.Cooldown,true);CD(lText,lFill,"万剑",game.formationReady,game.settings.formationCooldown*game.Cooldown,game.formationLearned);notice.text=game.clock<game.noticeUntil?game.notice:"";bool show=game.boss!=null&&game.boss.active&&game.boss.hp>0;bossPanel.gameObject.SetActive(show);bossWarning.text=show?game.BossWarning:"";warningPlate.gameObject.SetActive(!HasModal&&!string.IsNullOrEmpty(bossWarning.text));bool nova=show&&game.boss.state=="novaTell";novaBar.rectTransform.sizeDelta=new Vector2(nova?390*game.NovaProgress:0,7);novaCountdown.text=nova?$"{Mathf.Max(0,game.boss.next-game.clock):0.0} 秒后爆发":"";if(show){bool master=game.boss.kind=="master";bossName.text=master?"魔灵老祖 · 玄衡":"镇山傀儡";bossName.color=master?new Color(.94f,.64f,.7f):gold;bossFill.color=master?new Color(.67f,.14f,.24f):new Color(.55f,.41f,.21f);bossFill.rectTransform.sizeDelta=new Vector2(561*game.boss.hp/game.boss.maxHp,18);foreach(var image in bossPanel.GetComponentsInChildren<Image>())if(image.name=="masterSkull")image.enabled=master;}
   float left=game.gameCamera.transform.position.x*100-640;for(int i=0;i<worldHints.Length;i++)worldHints[i].text="";if(game.SheltersVisible){for(int i=0;i<2;i++){worldHints[i].text="归元草 · 护心庇所";worldHints[i].rectTransform.anchoredPosition=new Vector2(game.ShelterXs[i]-left-100,-474);}}else if(!game.endless&&game.room==1){worldHints[0].text="↓ 藏剑石窟";worldHints[0].rectTransform.anchoredPosition=new Vector2(3222-left-100,-440);worldHints[1].text=game.dashLearned?"跳跃 → Shift 越崖":"断桥 · 需踏云诀";worldHints[1].rectTransform.anchoredPosition=new Vector2(3800-left-100,-450);}else if(!game.endless&&game.room==2){worldHints[0].text="藏剑遗卷";worldHints[0].rectTransform.anchoredPosition=new Vector2(game.data.shrineX-left-100,-385);}int visibleTalents=0;for(int i=0;i<learned.Count;i++){int level=game.run?.Level(game.data.upgrades[i].id)??0;talentTiles[i].gameObject.SetActive(level>0);if(level>0){talentTiles[i].anchoredPosition=new Vector2(16+visibleTalents%3*32,-(274+visibleTalents/3*32));talentLevels[i].text=level>1?level.ToString():"";visibleTalents++;}}if(unlockPortrait)unlockPortrait.rectTransform.anchoredPosition=new Vector2(125,-150+Mathf.Sin((Time.unscaledTime-animAt)*1.5f)*6);}
  void CD(Text text,Image fill,string name,float ready,float duration,bool unlocked){float remain=Mathf.Max(0,ready-game.clock);text.text=!unlocked?name+" · 未悟":remain>0?$"{name} · {remain:0.0} 秒":name+" · 可用";fill.rectTransform.sizeDelta=new Vector2(unlocked?185*(1-Mathf.Clamp01(remain/duration)):0,8);fill.color=remain>0?gold:teal;}
  public void FitScreen(){float ratio=Screen.width/(float)Mathf.Max(1,Screen.height),target=16f/9;game.gameCamera.rect=ratio>target?new Rect((1-target/ratio)/2,0,target/ratio,1):new Rect(0,(1-ratio/target)/2,1,ratio/target); // Center a fixed design surface within wide/tall displays.
   root.pivot=new Vector2(.5f,.5f);if(modal)modal.anchoredPosition=new Vector2((root.rect.width-1280)/2,-(root.rect.height-720)/2);if(hud)hud.anchoredPosition=new Vector2((root.rect.width-1280)/2,-(root.rect.height-720)/2);}
